function catalogRows(allVenues=false){const snap=state.snapshot;if(!snap)return [];const same=snap.settings?.timeframe===state.settings.timeframe&&snap.settings?.period===state.settings.period;const enriched=new Map((same?snap.rows:[]).map(m=>[m.id,m]));return (allVenues?(snap.venues||snap.catalog||snap.rows||[]):(snap.catalog||snap.rows||[])).map(m=>({bars:[],move:null,...m,...enriched.get(m.id),price:m.price,volume24h:m.volume24h,change24h:m.change24h}));}
