function status(){
  const snap=state.snapshot,s=snap?.status,el=$('#connection-status');el.className='status-pill';
  let label='Savienojas';
  if(snap?.mode==='mock'){label='MOCK · simulācija';el.classList.add('demo');}
  else if(s?.phase==='error'){label='Datu kļūda';el.classList.add('error');}
  else if(!state.streamConnected){label='Atjauno savienojumu';}
  else if(['scanning','discovering'].includes(s?.phase)){label=s.phase==='scanning'?'Skenē '+s.progress+'/'+s.total:'Meklē tirgus';}
  else if(snap?.asOf&&Date.now()-snap.asOf<Math.max(180000,state.settings.refreshSeconds*3000)){label='Tirgus dati';el.classList.add('ok');}
  else if(snap?.asOf){label='Novecojuši dati';el.classList.add('error');}
  el.innerHTML='<span class="tiny-dot"></span>'+label;
  const notice=$('#notice'),messages=[];
  if(snap?.mode==='mock')messages.push('TESTA REŽĪMS: cenas un grafiki ir simulēti. Īstajiem datiem palaid “npm start”.');
  if(snap?.storageWarning)messages.push(snap.storageWarning);if(s?.error)messages.push(s.error+(snap?.rows?.length?' Redzams pēdējais saņemtais momentuzņēmums.':''));
  notice.hidden=!messages.length;if(messages.length)notice.innerHTML='<span>'+esc(messages.join(' '))+'</span><button data-view="settings">Datu avoti</button>';
  $('#scan-progress').textContent=s?.phase==='scanning'?'Ielādē '+s.progress+' / '+s.total:'Ik pēc '+state.settings.refreshSeconds+' s · pārlūka skeneris';
  $('#refresh-button').disabled=['scanning','discovering'].includes(s?.phase);$('#refresh-button').classList.toggle('spinning',['scanning','discovering'].includes(s?.phase));
}
