function render(){chrome();if(state.view==='dashboard')renderDashboard();else if(state.view==='database')renderDatabase();else if(state.view==='news')renderNews();else if(isMarkets())renderMarkets();else if(isSignals())renderSignals();else if(state.view==='listings')renderListings();else if(state.view==='results')renderResults();else renderSettings();}
async function loadSignals(append=false){
  if(append&&(!state.cursor||state.signalLoading))return;const id=++state.signalRequest;state.signalLoading=true;
  const strategy=['MOVES','LEVELS','SLOPE'].includes(state.view)?state.view:'ALL',assetClass=classView()||(scope()!=='ALL'?scope():state.asset);
  const q=new URLSearchParams({...currentFilters(),limit:'24',strategy:state.extraFilters.strategy!=='ALL'&&strategy!=='ALL'&&strategy!==state.extraFilters.strategy?'NONE':strategy==='ALL'?state.extraFilters.strategy:strategy,assetClass,q:state.query});if(append&&state.cursor)q.set('cursor',state.cursor);
  try{const d=await api('/api/signals?'+q);if(id!==state.signalRequest)return;state.signals=append?[...state.signals,...d.rows]:d.rows;state.cursor=d.nextCursor;}catch(e){toast(e.message);}finally{if(id===state.signalRequest){state.signalLoading=false;if(isSignals())render();}}
}
async function page(view){
  const request=state.pageRequest=(state.pageRequest||0)+1;
  if(state.view!==view){state.query='';$('#search').value='';state.classMode='markets';}
  state.marketLimit=100;state.view=view;if(view==='top10'){state.sort='volume';$('#sort').value='volume';}state.observer?.disconnect();$('#sidebar').classList.remove('open');
  const targetScope=({crypto:'CRYPTO',top10:'CRYPTO',stocks:'STOCK',commodities:'COMMODITY'})[view];
  if(targetScope){state.asset='ALL';state.settings=await api('/api/settings',{assetScope:targetScope,viewFilters:currentFilters(),activeProfileId:null});}
  if(request!==state.pageRequest)return;chrome();
  if(view==='dashboard'){renderDashboard();await loadDashboard();return;}
  if(isSignals()){state.signals=[];state.cursor=null;renderSignals();await loadSignals();return;}
  if(['listings','results','news','database'].includes(view)){
    $('#market-content').innerHTML='<div class="loading-state"><span class="loader"></span><strong>Ielādē datus</strong></div>';
    try{const data=await api('/api/'+view);if(request!==state.pageRequest)return;if(view==='news')state.news=data;else state[view]=data.rows;}
    catch(e){toast(e.message);}if(request===state.pageRequest)render();
  }else render();
}
async function loadDashboard(){
  const request=state.dashboardRequest=(state.dashboardRequest||0)+1,panels=visiblePanels();
  const entries=await Promise.all(panels.filter(p=>p.id!=='TOP10').map(async p=>{try{const q=new URLSearchParams({...currentFilters(),limit:'4',strategy:state.extraFilters.strategy!=='ALL'&&p.strategy!=='ALL'&&p.strategy!==state.extraFilters.strategy?'NONE':p.strategy==='ALL'?state.extraFilters.strategy:p.strategy,assetClass:p.assetClass==='ALL'?(scope()==='ALL'?state.asset:scope()):p.assetClass,q:state.query});return [p.id,(await api('/api/signals?'+q)).rows];}catch{return [p.id,[]];}}));
  if(request!==state.dashboardRequest||state.view!=='dashboard')return;state.dashboard=Object.fromEntries(entries);state.signals=[...new Map(entries.flatMap(([,rows])=>rows).map(s=>[s.id,s])).values()];renderDashboard();
}
function visiblePanels(){return SCANNERS.filter(p=>(state.settings.visibleScanners||SCANNER_IDS).includes(p.id)&&(scope()==='ALL'||p.assetClass==='ALL'||p.assetClass===scope()));}
