for(const [id,key]of [['exchange-filter','exchange'],['market-type-filter','marketType'],['strategy-filter','strategy'],['signal-tf-filter','signalTf']])$('#'+id).addEventListener('change',e=>{state.extraFilters[key]=e.target.value;persistFilters();});
$('#volume-filter').addEventListener('input',e=>{state.extraFilters.minVolume=Math.max(0,+e.target.value||0);clearTimeout(state.filterTimer);state.filterTimer=setTimeout(()=>persistFilters(),350);render();});
$('#direction-filter').addEventListener('change',e=>{state.direction=e.target.value;persistFilters();});
$('#saved-only-filter').addEventListener('change',e=>{state.extraFilters.onlySaved=e.target.checked;persistFilters();});
document.addEventListener('change',e=>{if(e.target.id==='result-strategy'){state.resultStrategy=e.target.value;renderResults();}});
setInterval(()=>{$$('[data-countdown]').forEach(el=>{const seconds=Math.ceil((+el.dataset.countdown-Date.now())/1000);el.textContent=seconds>0?'· pēc '+Math.floor(seconds/3600)+' h '+Math.floor(seconds%3600/60)+' min '+seconds%60+' s':'· plānotais laiks pagājis; pārbaudi biržas statusu';});},1000);
let audio;
function beep(){try{audio??=new AudioContext();audio.resume();const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.connect(gain);gain.connect(audio.destination);oscillator.frequency.value=660;gain.gain.setValueAtTime(.04,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.2);oscillator.start();oscillator.stop(audio.currentTime+.2);}catch{}}
async function configure(patch){state.settings=await api('/api/settings',patch);render();if(state.view==='dashboard')await loadDashboard();}
async function openInstrument(id,tf=state.settings.timeframe,signal=null){
  const token=state.detailRequest=(state.detailRequest||0)+1;state.detailLoading=true;$('#detail-content').innerHTML='<div class="loading-state"><span class="loader"></span><strong>Ielādē instrumenta '+esc(tf)+' grafiku</strong></div>';if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
  try{const d=await api('/api/instrument?'+new URLSearchParams({id,tf}));if(token!==state.detailRequest)return;if(!d?.market)throw new Error('Instruments nav pieejams');for(const s of d.signals||[])state.extraSignals.set(s.id,s);showDetail({...d,bars:d.market.bars,mode:'market',signal});}
  catch(e){if(token===state.detailRequest)$('#detail-content').innerHTML=empty('Avots grafiku neatdeva',e.message);}
  finally{if(token===state.detailRequest)state.detailLoading=false;}
}
async function openListing(id){
  const token=state.detailRequest=(state.detailRequest||0)+1;$('#detail-content').innerHTML='<div class="loading-state"><span class="loader"></span><strong>Ielādē listinga vēsturi</strong></div>';if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
  try{const d=await api('/api/listing?id='+encodeURIComponent(id));if(token!==state.detailRequest)return;if(!d?.listing)throw new Error('Paziņojums nav atrasts');showDetail({...d,mode:'listing',bars:d.market?.bars||[]});}catch(e){if(token===state.detailRequest)$('#detail-content').innerHTML=empty('Listingam grafiks nav pieejams',e.message);}
}
function showDetail(context){
  state.detail=context;const {market:m,bars=[],signal,listing}=context,snapshot=Boolean(signal&&context.mode!=='market');
  if(!m){$('#detail-content').innerHTML='<h2>'+esc(listing?.title||'Listing')+'</h2><p class="detail-note">'+esc(context.note||'Cenu dati nav pieejami.')+'</p><a class="button" target="_blank" rel="noopener noreferrer" href="'+esc(listing.sourceUrl)+'">Oficiālais paziņojums ↗</a>';return;}
  const up=signal?isUp(signal.direction):(m.move??0)>=0,tf=m.timeframe||signal?.timeframe||state.settings.timeframe;
  const markerList=listing?[{ts:listing.announcedAt,label:'Paziņojums',color:'#eab777'},...(listing.tradingStartAt?[{ts:listing.tradingStartAt,label:'Tirdzniecības sākums',color:'#ad9af3'}]:[])]:signal&&!snapshot?[{ts:signal.createdAt,label:'Signāls',color:'#eab777'}]:[];
  $('#detail-content').innerHTML='<div class="detail-heading">'+avatar(m)+'<div><h2>'+esc(m.base)+' / '+esc(m.quote||'USDT')+'</h2><p>'+esc(sourceName(m.source))+' · '+esc(tf)+' · '+(snapshot?'SIGNĀLA MOMENTUZŅĒMUMS':listing?'LISTINGA VĒSTURE':'TIRGUS GRAFIKS')+'</p></div></div>'+(listing?'<h3 class="listing-detail-title">'+esc(listing.title)+'</h3><p class="detail-note">Paziņojums: '+date(listing.announcedAt)+(listing.tradingStartAt?' · tirdzniecība plānota '+date(listing.tradingStartAt):' · tirdzniecības sākums nav zināms')+'</p>':'')+'<div class="detail-price">'+price(snapshot?signal.entry:m.price)+'<span class="'+(up?'positive':'negative')+'">'+(signal?esc(signal.direction)+' · '+signal.strategy:pct(m.change24h)+' · 24h')+'</span></div>'+(signal?'<div class="detail-mode"><button data-detail-mode="snapshot" class="'+(snapshot?'selected':'')+'">Signāla brīdī</button><button data-detail-mode="market" class="'+(!snapshot?'selected':'')+'">Pēc signāla / tirgus</button></div>':'')+(!snapshot&&!listing?'<div class="detail-timeframes">'+['5m','15m','1h','4h','1d'].map(t=>'<button data-detail-tf="'+t+'" class="'+(t===tf?'selected':'')+'">'+t+'</button>').join('')+'<button class="text-button" id="refresh-detail">Atjaunot datus ↻</button></div>':'')+'<div class="chart-wrap" id="interactive-chart"></div><p class="detail-note">'+(snapshot?'Šis grafiks saglabā tikai signāla brīdī zināmās sveces.':listing?'Grafiks sākas aptuveni stundu pirms paziņojuma, ja avotā tajā laikā bija šis tirgus. Rādām līdz 24 stundām pēc paziņojuma.':'Pēdējā cenas atjaunošana: '+date(m.priceAsOf)+'. Grafika intervāla maiņa nemaina fona skenera intervālu.')+'</p>'+(listing?.referencePrice?'<p class="detail-note">Cenas atskaite: '+price(listing.referencePrice)+' · '+date(listing.referenceAt)+' · '+(listing.referenceKind==='pre-announcement-candle'?'pēdējās pieejamās noslēgtās 5m sveces cena pirms paziņojuma':'pirmoreiz novērotā cena')+' · izmaiņa '+pct(listing.changeSince)+'</p>':'')+'<div class="detail-metrics">'+(signal?[['Signāls',date(signal.createdAt)],['Līmenis',price(signal.levelPrice)],['TP',price(signal.tp)],['SL',price(signal.sl)]]:[['24h apjoms',compact(m.volume24h)+' USDT'],['RVOL',m.activity?.rvol==null?'Trūkst pārklājuma':m.activity.rvol.toFixed(2)+'×'],['Apjoma viļņa sākums',m.activity?.waveStart?date(m.activity.waveStart.ts):'Nav noteikts'],['Kopš viļņa sākuma',pct(m.activity?.waveStart?.changePct)]]).map(([k,v])=>'<div class="detail-metric">'+esc(k)+'<strong>'+esc(v)+'</strong></div>').join('')+'</div>'+(context.venues?.length?'<section class="venue-section"><h3>Pieejamie tirgi un cenas</h3><p class="detail-note">Katram tirgum ir savs simbols, līguma veids un cenas laiks.</p><div class="table-wrap"><table class="market-table venue-table"><thead><tr><th>BIRŽA / SIMBOLS</th><th>VEIDS</th><th>CENA</th><th>LAIKS</th><th></th></tr></thead><tbody>'+context.venues.map(v=>'<tr><td><button class="text-button" data-market="'+esc(v.id)+'">'+esc(v.exchange.toUpperCase())+' · '+esc(v.symbol)+'</button></td><td>'+esc(v.marketType)+'</td><td>'+price(v.price)+'</td><td>'+date(v.priceAsOf)+'</td><td><a target="_blank" rel="noopener noreferrer" href="'+esc(v.tradeUrl)+'">Birža ↗</a></td></tr>').join('')+'</tbody></table></div></section>':'')+(context.signals?.length?'<section class="instrument-history"><h3>Instrumenta signālu vēsture</h3>'+context.signals.slice(0,20).map(s=>'<button class="instrument-signal" data-signal="'+s.id+'"><span>'+s.strategy+' · '+s.direction+' · '+s.timeframe+'</span><time>'+date(s.createdAt)+'</time></button>').join('')+'</section>':'')+'<div class="detail-footer"><a class="button primary" target="_blank" rel="noopener noreferrer" href="'+esc(m.tradeUrl)+'">Skatīt biržas tirgu ↗</a><a class="button" target="_blank" rel="noopener noreferrer" href="https://www.tradingview.com/chart/?symbol='+encodeURIComponent(m.exchange.toUpperCase()+':'+m.base+'USDT'+(m.marketType==='PERP'?'.P':''))+'">TradingView ↗</a><button class="button" data-star="'+esc(m.id)+'">'+(saved(m.id)?'★ Izlasē':'☆ Saglabāt izlasē')+'</button>'+(listing?'<a class="button" target="_blank" rel="noopener noreferrer" href="'+esc(listing.sourceUrl)+'">Oficiālais paziņojums ↗</a>':'')+'</div>';
  mountChart($('#interactive-chart'),{bars,overlay:signal,markers:markerList,wave:!snapshot&&!listing?m.activity?.waveStart:null,initialLimit:listing?160:state.chartLimit});if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
}
const methodology='<div class="eyebrow">MARKETPULSE PERSONAL</div><h2>Ko tieši skeneris aprēķina?</h2><h3>Publiski dati</h3><p>Binance, Bybit un OKX publiskie spot un USDT perpetual tirgi. Atslēga nav vajadzīga. Avoti var ierobežot piekļuvi pēc atrašanās vietas vai IP. Kļūdas redzamas iestatījumos. Programma neveic tirdzniecības rīkojumus.</p><h3>MOVES</h3><p>Noslēgtas sveces (close/open − 1) × 100. Kripto bāzes slieksnis 0.8%, paaugstināts līdz 1.8 ATR%; papildus izmanto novirzi pret iepriekšējām 30 svecēm. Akciju un izejvielu profili izmanto adaptīvus sliekšņus. Signālu cooldown ir 2–3 sveces.</p><h3>LEVELS un SLOPE</h3><p>Līmeņi veidojas no apstiprinātiem swing pivot punktiem, kas apvienoti ATR tolerances klasteros. Nepieciešamas vismaz trīs reakcijas. Trendlīnijas meklējam ar deterministisku konsensa atlasi un regresiju; nepieciešami vismaz trīs pieskārieni un 12 sveču garums. Signāls rodas pie jauna pietuvojuma, retesta vai izlaušanās.</p><h3>Markets: septiņu dienu salīdzinājums</h3><p>RVOL = izvēlētā pilnībā noslēgtā perioda USDT apjoms / iepriekšējo tāda paša garuma periodu vidējais pēdējās septiņās dienās. Pašreizējais periods bāzē neietilpst. 7d periods tiek salīdzināts ar iepriekšējām atsevišķām septiņām dienām. Ja datu pārklājums ir zem 95%, RVOL un vērtējums nav pieejami. Vērtējums 0–100 kombinē log(RVOL) un relatīvo cenu kustību.</p><h3>Paziņojumi un identitāte</h3><p>Biržu jaunumi aptver Binance, Bybit, OKX un Bitget oficiālos paziņojumus un jaunatklātus tirgus izmantotajos avotos. Pirmā tirgu saraksta ielāde neveido tūkstošiem viltus jaunu listing signal. Alpha tokenus nesavienojam ar vienāda simbola biržas tokenu. Ja norādīta pirmoreiz novērotā cena, tās laiks redzams atsevišķi: tā nav apsolīta cena paziņojuma brīdī. Precīzs tirdzniecības sākums netiek uzminēts.</p><h3>Rezultāti</h3><p>MFE/MAE izmanto tikai pilnas sveces, kas sākas pēc signāla izveides. Novērošanas logs: MOVES 24, LEVELS/SLOPE 48 sveces. MFE ir maksimāla labvēlīga kustība, nevis realizēta peļņa. Ja viena svece skar gan TP, gan SL, secība ir nezināma. Kripto demo apjoms $1000, akciju instrumentiem $10000, izejvielām 0.5 lot; bez zināmām kontrakta vienībām USD peļņa netiek izdomāta. Komisijas, spread, slippage un funding nav atskaitīti.</p><h3>Personīgā lietošana</h3><p>Nav lietotāju kontu, abonementu vai maksājumu. Šī lapa ir publicēta GitHub Pages. Izlase, iestatījumi un individuālā vēsture glabājas šī pārlūka IndexedDB krātuvē. Individuālā skenēšana darbojas atvērtā lapā; publisko datu padevi aptuveni ik 15 minūtēm atjauno GitHub Actions. Publiskie signāli var atšķirties no tavas individuālās atlases. Datu avota kļūdas netiek automātiski aizstātas ar simulāciju.</p><p>Tikai informācijai un izglītošanai. Nav finanšu konsultācija. Peļņa netiek garantēta.</p>';
document.addEventListener('click',async e=>{
  try{
    const detailTf=e.target.closest('[data-detail-tf]');if(detailTf){await openInstrument(state.detail.market.id,detailTf.dataset.detailTf,state.detail.signal);return;}
    const detailMode=e.target.closest('[data-detail-mode]');if(detailMode){const s=state.detail.signal;if(detailMode.dataset.detailMode==='snapshot')showDetail({market:s.market,bars:s.snapshot,signal:s,mode:'snapshot'});else await openInstrument(s.marketId,s.timeframe,s);return;}
    if(e.target.closest('#refresh-detail')){await openInstrument(state.detail.market.id,state.detail.market.timeframe,state.detail.signal);return;}
    const listingButton=e.target.closest('[data-listing]');if(listingButton){await openListing(listingButton.dataset.listing);return;}
    const resultDays=e.target.closest('[data-result-days]');if(resultDays){state.resultDays=+resultDays.dataset.resultDays;renderResults();return;}
    const scopeButton=e.target.closest('[data-scope]');if(scopeButton){state.asset='ALL';$('#asset-filter').value='ALL';await configure({assetScope:scopeButton.dataset.scope,viewFilters:currentFilters(),activeProfileId:null});const v=classView()||state.view==='top10'?'markets':state.view;await page(v);return;}
    const openScanner=e.target.closest('[data-open-scanner]');if(openScanner){const p=SCANNERS.find(p=>p.id===openScanner.dataset.openScanner);await page(p.view);if(['stocks','commodities'].includes(p.view)){state.classMode='signals';await loadSignals();render();}return;}
    if(e.target.closest('#show-all-scanners')){await configure({visibleScanners:SCANNER_IDS});return;}
    if(e.target.closest('#more-database')){state.marketLimit+=100;renderDatabase();return;}
    const starEl=e.target.closest('[data-star]');if(starEl){e.stopPropagation();const id=starEl.dataset.star,ids=new Set(state.settings.saved);ids.has(id)?ids.delete(id):ids.add(id);await configure({saved:[...ids]});if($('#detail-dialog').open)showDetail(state.detail);return;}
    const signal=e.target.closest('[data-signal]');if(signal){const s=state.signals.find(s=>s.id===signal.dataset.signal)||state.extraSignals.get(signal.dataset.signal);if(s)showDetail({market:s.market,bars:s.snapshot,signal:s});return;}
    const result=e.target.closest('[data-result]');if(result){const s=state.results.find(r=>r.signal.id===result.dataset.result)?.signal;if(s)showDetail({market:s.market,bars:s.snapshot,signal:s});return;}
    const market=e.target.closest('[data-market]');if(market){await openInstrument(market.dataset.market);return;}
    const mode=e.target.closest('[data-class-mode]');if(mode){state.classMode=mode.dataset.classMode;state.marketLimit=100;if(isSignals()){state.signals=[];await loadSignals();}render();return;}
    if(e.target.closest('#more-markets')){state.marketLimit+=100;renderMarkets();return;}
    const v=e.target.closest('[data-view]');if(v){await page(v.dataset.view);return;}
    const tf=e.target.closest('[data-tf]');if(tf){await configure({timeframe:tf.dataset.tf});toast('Skenera intervāls saglabāts. Ielādē jaunās sveces.');return;}
    const period=e.target.closest('[data-period]');if(period){await configure({period:period.dataset.period});toast('Markets periods saglabāts. Ielādē vēsturi.');return;}
    const dir=e.target.closest('[data-direction]');if(dir){state.direction=dir.dataset.direction;persistFilters();$$('[data-direction]').forEach(x=>x.classList.toggle('selected',x===dir));render();return;}
    const layout=e.target.closest('[data-layout]');if(layout){state.layout=layout.dataset.layout;render();return;}
    const zoom=e.target.closest('[data-chart-limit]');if(zoom){state.chartLimit=+zoom.dataset.chartLimit;showDetail(state.detail);return;}
    const close=e.target.closest('[data-close]');if(close)$('#'+close.dataset.close).close();
    if(e.target.closest('#load-more'))await loadSignals(true);
    if(e.target.closest('#preview-sound'))beep();
  }catch(error){toast(error.message);}
});
document.addEventListener('submit',async e=>{if(e.target.id!=='settings-form')return;e.preventDefault();const f=new FormData(e.target);try{await configure({source:f.get('source'),maxMarkets:+f.get('maxMarkets'),refreshSeconds:+f.get('refreshSeconds'),minVolume24h:+f.get('minVolume24h'),minTradfiVolume24h:+f.get('minTradfiVolume24h'),assetClass:f.get('assetClass'),sound:f.get('sound')==='on'});toast('Iestatījumi saglabāti. Sākas jauna skenēšana.');}catch(error){toast(error.message);}});
$('#search').addEventListener('input',e=>{state.marketLimit=100;state.query=e.target.value.trim();clearTimeout(state.searchTimer);if(state.view==='dashboard')state.searchTimer=setTimeout(()=>loadDashboard(),250);else if(isSignals())state.searchTimer=setTimeout(()=>loadSignals(),250);else render();});
$('#sort').addEventListener('change',e=>{state.sort=e.target.value;render();});
$('#filter-button').addEventListener('click',()=>{$('#filter-panel').hidden=!$('#filter-panel').hidden;$('#filter-button').setAttribute('aria-expanded',String(!$('#filter-panel').hidden));});
$('#asset-filter').addEventListener('change',e=>{state.asset=e.target.value;persistFilters({assetScope:state.asset});});
for(const [id,key]of [['min-move','minMove'],['min-rvol','minRvol']])$('#'+id).addEventListener('input',e=>{state[key]=Math.max(0,+e.target.value||0);clearTimeout(state.filterTimer);state.filterTimer=setTimeout(()=>persistFilters(),350);render();});
$('#reset-filters').addEventListener('click',()=>{hydrateFilters(FILTER_DEFAULTS);persistFilters({assetScope:classView()||'ALL',activeProfileId:null});});
document.addEventListener('change',async e=>{
  if(e.target.matches('[data-scanner-toggle]')){const key=e.target.dataset.scannerToggle,visible=new Set(state.settings.visibleScanners||SCANNER_IDS);e.target.checked?visible.add(key):visible.delete(key);e.target.disabled=true;try{await configure({visibleScanners:[...visible]});}catch(error){toast(error.message);chrome();}finally{e.target.disabled=false;}}
  if(e.target.id==='db-exchange'){state.dbExchange=e.target.value;state.marketLimit=100;renderDatabase();}
  if(e.target.id==='db-type'){state.dbType=e.target.value;state.marketLimit=100;renderDatabase();}
  if(e.target.id==='db-history'){state.dbHistory=e.target.checked;state.marketLimit=100;renderDatabase();}
});
document.addEventListener('change',e=>{if(e.target.id==='listing-exchange'){state.listingExchange=e.target.value;renderListings();}if(e.target.id==='listing-type'){state.listingType=e.target.value;renderListings();}});
$('#refresh-button').addEventListener('click',async()=>{try{await api('/api/scan',{});toast('Skenēšana pieprasīta.');}catch(e){toast(e.message);}});
$('#menu-button').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#sound-button').addEventListener('click',async()=>{try{beep();await configure({sound:!state.settings.sound});toast(state.settings.sound?'Skaņa ieslēgta šajā pārlūkā.':'Skaņa izslēgta.');}catch(e){toast(e.message);}});
for(const id of ['method-button','criteria-button'])$('#'+id).addEventListener('click',()=>{$('#info-content').innerHTML=methodology;$('#info-dialog').showModal();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus();}if(e.key==='Enter'&&e.target.matches('tr[data-market]'))e.target.click();});
$('#detail-dialog').addEventListener('close',()=>{state.detailRequest=(state.detailRequest||0)+1;state.detailLoading=false;});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}}));
async function init(){
  try{const [snap,config]=await Promise.all([api('/api/markets'),api('/api/settings')]);state.snapshot=snap;state.settings=config.settings;state.sources=config.sources;hydrateFilters(state.settings.viewFilters||FILTER_DEFAULTS);render();await page(state.view);}
  catch(e){$('#market-content').innerHTML=empty('Nav savienojuma ar vietējo serveri',e.message);}
  state.streamConnected=true;status();
  subscribe(async(event,data)=>{
    if(event==='status'){state.snapshot??={rows:[]};state.snapshot.status=data;status();}
    if(event==='settings'){state.settings=data;chrome();}
    if(event==='snapshot'){state.snapshot=data;state.settings=data.settings;if(state.view==='settings'&&$('#settings-form'))chrome();else render();if(state.view==='dashboard')loadDashboard();else if(isSignals())loadSignals();else if(state.view==='database'){state.database=(await api('/api/database')).rows;renderDatabase();}else if(state.view==='listings'){state.listings=(await api('/api/listings')).rows;renderListings();}else if(state.view==='results'){state.results=(await api('/api/results')).rows;renderResults();}}
    if(event==='signal'){if(state.settings.sound&&data.fresh)beep();if(data.fresh)toast(data.market.base+' · '+data.strategy+' · '+data.direction);}
  });
  $('#export-link').addEventListener('click',async event=>{event.preventDefault();try{await downloadExport();toast('Vēstures kopija lejupielādēta.');}catch(e){toast(e.message);}});
  installTour({navigate:page});
  setInterval(status,10000);
}
init();
